// Faraday demo (simulated model)
var se_db=60;
var ratio=Math.pow(10,se_db/20);
console.log('SE '+se_db+'dB -> field reduced '+ratio.toExponential(0)+'x');
console.log('inside: radio silence');

// SE table demo (simulated model)
var dbs=[20,40,60,80];
for(var i=0;i<dbs.length;i++){console.log(dbs[i]+'dB = '+Math.pow(10,dbs[i]/20)+'x');}
console.log('dB: the shielding language');

// EMP demo (simulated model)
console.log('E1 pulse: 50kV/m, 5ns rise');
console.log('188-125: facility holds (tested)');

// TEMPEST demo (simulated model)
var leak=80, limit=20;
console.log('emanation '+leak+'dBuV vs limit '+limit+': '+(leak>limit?'LEAKING':'contained'));
console.log('shield to contain');

// Fabric demo (simulated model)
var fabrics=[['Ni-Cu ripstop',70],['silver mesh',50]];
for(var i=0;i<fabrics.length;i++){console.log(fabrics[i][0]+': '+fabrics[i][1]+'dB');}
console.log('flexible shielding rated');

// Bag demo (simulated model)
var sigs=['cell','wifi','bt','gps'], blocked=0;
for(var i=0;i<sigs.length;i++){blocked++;console.log(sigs[i]+': blocked');}
console.log(blocked+'/'+sigs.length+' signals blocked');

// Skin depth demo (simulated model)
var f=1e9, mu=4*Math.PI*1e-7, sig=5.8e7;
var d=Math.sqrt(2/(2*Math.PI*f*mu*sig))*1e6;
console.log('copper @1GHz skin depth='+d.toFixed(2)+' microns');
console.log('physics picks the metal');

// Aperture demo (simulated model)
var wall=90, hole=30;
console.log('wall '+wall+'dB, hole '+hole+'dB -> enclosure '+Math.min(wall,hole)+'dB');
console.log('worst hole wins');

// SCIF demo (simulated model)
console.log('SCIF: 100dB RF + acoustic + access');
console.log('accredited shielded space');

// Test demo (simulated model)
var bands=[['100MHz',75],['1GHz',68],['10GHz',55]];
for(var i=0;i<bands.length;i++){console.log(bands[i][0]+': '+bands[i][1]+'dB');}
console.log('swept and proven');

// Grounding demo (simulated model)
console.log('single-point ground: no loops');
console.log('filters on every penetration');

// Field demo (simulated model)
console.log('field tent: 42dB deployed in 10min');
console.log('mobile shielding works');

// Maintenance demo (simulated model)
var se=[80,76,71];
for(var i=0;i<se.length;i++){console.log('year '+i+': '+se[i]+'dB');}
console.log('re-test scheduled');

// Threat demo (simulated model)
var threat={freq:'1MHz-10GHz',level:'60dB'};
console.log('threat: '+threat.freq+' @ '+threat.level);
console.log('design follows threat');

// Picture demo (simulated model)
var p=['threat','material','seams','ground','test','maintain'];
for(var i=0;i<p.length;i++){console.log((i+1)+'. '+p[i]);}
console.log('shielding discipline complete');
